function dateRangeInfo(dates) {
  if (!dates.length) return null;
  const days = dates.map(value => Date.parse(value.slice(0,10) + "T00:00:00Z"));
  const earliest = Math.min(...days), latest = Math.max(...days);
  return {earliest:new Date(earliest).toISOString().slice(0,10),
    latest:new Date(latest).toISOString().slice(0,10), daysBetween:(latest-earliest)/86400000};
}
console.log(dateRangeInfo(["2025-01-10", "2025-01-15T12:00:00Z", "2024-12-31"]));

