function groupByCity(users) {
  const groups = new Map();
  for (const user of users) {
    const city = user.address.city;
    if (!groups.has(city)) groups.set(city, []);
    groups.get(city).push(user.name);
  }
  return [...groups].sort(([a],[b])=>a.localeCompare(b)).map(([city,names])=>({city,names:names.sort((a,b)=>a.localeCompare(b))}));
}
console.log(groupByCity([{name:"Zara",address:{city:"Dushanbe"}},{name:"Alex",address:{city:"Dushanbe"}},{name:"Boris",address:{city:"Khorog"}}]));

